// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { foregroundTracker } from "../../../main/frontend/graph-explorer/foreground-tracker.ts";

test("background work waits until every foreground query has settled, failed ones included", async () => {
  const tracker = foregroundTracker();
  await tracker.idle();
  let finishFirst;
  let failSecond;
  const first = tracker.track(new Promise((resolve) => (finishFirst = resolve)));
  const second = tracker.track(new Promise((_, reject) => (failSecond = reject)));
  let idle = false;
  const waiting = tracker.idle().then(() => (idle = true));
  finishFirst("done");
  await first;
  await new Promise(setImmediate);
  assert.equal(idle, false, "one query is still running");
  failSecond(new Error("refused"));
  await assert.rejects(second);
  await waiting;
  assert.equal(idle, true);
});
